// openPager hands the document to the system pager.
//
// It survives for one source and deliberately: `less` handles a gigabyte and
// follows it, which a viewport holding the whole document in memory never will.
// Every other pager path in the application is gone.
func (m Model) openPager() (tea.Model, tea.Cmd) {
	src, ok := m.pageable()
	if !ok {
		return m, nil
	}
	return m, tea.ExecProcess(src.PagerCmd(), func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// copyContent puts the document's own text on the clipboard — the source, not
// what `f` currently renders: a rendered Markdown has its markers taken out,
// and pasting that instead of the file itself would be the wrong text under
// the right key.
func (m Model) copyContent() (tea.Model, tea.Cmd) {
	if !m.hasDocument() {
		return m, nil
	}
	text := m.doc.Text
	return m, func() tea.Msg {
		return ContentCopiedMsg{Err: clipboard.WriteAll(text)}
		return m, launchDetachedCmd(bin, args)
	}

	// No terminal detected (common on WSL) — report to user
	return m, m.footer.Warn("No terminal detected — set App.TerminalCommand in config")
}

// openTerminalInPlace suspends the TUI and opens a shell in the given directory.
func (m Model) openTerminalInPlace(targetPath string) (tea.Model, tea.Cmd) {
	shell := detectShell()
	if shell == "/bin/sh" {
		if _, err := os.Stat("/bin/bash"); err == nil {
			shell = "/bin/bash"
		}
	}
	cmd := exec.Command(shell)
	cmd.Dir = targetPath
	return m, tea.ExecProcess(cmd, func(err error) tea.Msg {
		if err != nil {
			log.Printf("ERROR [workspaces] terminal exit: %v", err)
		}
		return TerminalExitMsg{}
	})
}

