func (m Model) handleTerminalOpened(msg TerminalOpenedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [workspaces] open terminal: %v", msg.Error)
		return m, m.footer.Error("Failed to open terminal — check logs")
	}
